    string subStrHash(string s, int power, int modulo, int k, int hashValue) {
        int n = s.size();
        long long curr = 0;
        long long pk = 1;
        for (int i = 0; i < k; i++) {
            if (i > 0) pk = (pk * power) % modulo;
        }
        for (int i = n - 1; i >= n - k; i--) {
            long long val = s[i] - 'a' + 1;
            curr = (curr * power + val) % modulo;
        }
        int resIdx = -1;
        if (curr == hashValue) resIdx = n - k;
        for (int i = n - k - 1; i >= 0; i--) {
            long long valOut = s[i + k] - 'a' + 1;
            long long valIn = s[i] - 'a' + 1;
            curr = ((curr - valOut * pk) % modulo + modulo) % modulo;
            curr = (curr * power + valIn) % modulo;
            if (curr == hashValue) resIdx = i;
        }
        return s.substr(resIdx, k);
    }
};

class Solution {
    public String subStrHash(String s, int power, int modulo, int k, int hashValue) {
        int n = s.length();
        long curr = 0;
        long pk = 1;
        for (int i = 0; i < k; i++) {
            if (i > 0) pk = (pk * power) % modulo;
        }
        for (int i = n - 1; i >= n - k; i--) {
            long val = s.charAt(i) - 'a' + 1;
            curr = (curr * power + val) % modulo;
        }
        int resIdx = -1;
        if (curr == hashValue) resIdx = n - k;
        for (int i = n - k - 1; i >= 0; i--) {
            long valOut = s.charAt(i + k) - 'a' + 1;
            long valIn = s.charAt(i) - 'a' + 1;
            curr = ((curr - valOut * pk) % modulo + modulo) % modulo;
            curr = (curr * power + valIn) % modulo;
            if (curr == hashValue) resIdx = i;
        }
        return s.substring(resIdx, resIdx + k);
    }
}

var subStrHash = function(s, power, modulo, k, hashValue) {
    const n = s.length;
    const mod = BigInt(modulo);
    const pow = BigInt(power);
    let curr = 0n;
    let pk = 1n;
    for (let i = 0; i < k; i++) {
        if (i > 0) pk = (pk * pow) % mod;
    }
    for (let i = n - 1; i >= n - k; i--) {
        const val = BigInt(s.charCodeAt(i) - 96);
        curr = (curr * pow + val) % mod;
    }
    let resIdx = -1;
    if (Number(curr) === hashValue) resIdx = n - k;
    for (let i = n - k - 1; i >= 0; i--) {
        const valOut = BigInt(s.charCodeAt(i + k) - 96);
        const valIn = BigInt(s.charCodeAt(i) - 96);
        curr = ((curr - valOut * pk) % mod + mod) % mod;
        curr = (curr * pow + valIn) % mod;
        if (Number(curr) === hashValue) resIdx = i;
    }
    return s.slice(resIdx, resIdx + k);
};
